import { and, eq, isNull, or, sql } from "drizzle-orm";

import { createDb } from "../../../db";
import {
  humanPrincipals,
  principals,
  systemRoleGrants,
  systemRoles,
} from "../../../db/domain-schema";
import { type AuthEnvironment } from "../../auth";
import { type Actor } from "../authorization/service";
import { M1Error } from "../errors";
import {
  auditStatementWhen,
  enforceRateLimit,
  outboxStatementWhen,
} from "../shared/infrastructure";

async function resolveHumanPrincipal(database: D1Database, identifier: string) {
  const db = createDb(database);
  const principal = await db
    .select({
      principalId: principals.id,
      principalStatus: principals.status,
      userId: humanPrincipals.userId,
      humanStatus: humanPrincipals.status,
      disabled: humanPrincipals.disabled,
    })
    .from(principals)
    .innerJoin(humanPrincipals, eq(humanPrincipals.principalId, principals.id))
    .where(or(eq(principals.id, identifier), eq(humanPrincipals.userId, identifier)))
    .get();
  if (!principal) return undefined;

  const rootGrant = await db
    .select({ id: systemRoleGrants.id })
    .from(systemRoleGrants)
    .innerJoin(systemRoles, eq(systemRoles.id, systemRoleGrants.roleId))
    .where(
      and(
        eq(systemRoleGrants.principalId, principal.principalId),
        isNull(systemRoleGrants.revokedAt),
        eq(systemRoles.key, "root"),
      ),
    )
    .get();

  return {
    principal_id: principal.principalId,
    principal_status: principal.principalStatus,
    user_id: principal.userId,
    human_status: principal.humanStatus,
    disabled: principal.disabled ? 1 : 0,
    is_root: rootGrant ? 1 : 0,
  };
}

async function activeRootCount(database: D1Database) {
  const row = await createDb(database)
    .select({ count: sql<number>`count(*)` })
    .from(principals)
    .innerJoin(humanPrincipals, eq(humanPrincipals.principalId, principals.id))
    .innerJoin(systemRoleGrants, eq(systemRoleGrants.principalId, principals.id))
    .innerJoin(systemRoles, eq(systemRoles.id, systemRoleGrants.roleId))
    .where(
      and(
        eq(principals.type, "human"),
        eq(principals.status, "active"),
        eq(humanPrincipals.status, "active"),
        eq(humanPrincipals.disabled, false),
        isNull(systemRoleGrants.revokedAt),
        eq(systemRoles.key, "root"),
      ),
    )
    .get();
  return row?.count ?? 0;
}

export async function setUserDisabled(
  environment: AuthEnvironment,
  actor: Actor,
  identifier: string,
  disabled: boolean,
  request: Request,
) {
  await enforceRateLimit(environment, request, disabled ? "user-disable" : "user-enable", 60, 60);
  const target = await resolveHumanPrincipal(environment.DB, identifier);
  if (!target) throw new M1Error(404);
  if (
    target.principal_status === (disabled ? "disabled" : "active") &&
    target.human_status === (disabled ? "disabled" : "active")
  ) {
    if (disabled) {
      await environment.DB.prepare("DELETE FROM session WHERE user_id = ?")
        .bind(target.user_id)
        .run();
    }
    return {
      status: disabled ? ("disabled" as const) : ("active" as const),
      userId: target.user_id,
    };
  }
  if (disabled && target.is_root === 1 && (await activeRootCount(environment.DB)) <= 1) {
    throw new M1Error(409);
  }

  const now = Date.now();
  const nextStatus = disabled ? "disabled" : "active";
  const mutation = environment.DB.prepare(
    disabled
      ? `UPDATE principals
              SET status = 'disabled', disabled_at = ?, updated_at = ?
            WHERE id = ? AND type = 'human' AND status = 'active'
              AND (
                NOT EXISTS (
                  SELECT 1
                    FROM system_role_grants AS own_grant
                    JOIN system_roles AS own_role ON own_role.id = own_grant.role_id
                   WHERE own_grant.principal_id = principals.id
                     AND own_grant.revoked_at IS NULL
                     AND own_role.key = 'root'
                )
                OR (
                  SELECT COUNT(*)
                    FROM principals AS root_principal
                    JOIN human_principals AS root_human ON root_human.principal_id = root_principal.id
                    JOIN system_role_grants AS root_grant ON root_grant.principal_id = root_principal.id
                    JOIN system_roles AS root_role ON root_role.id = root_grant.role_id
                   WHERE root_principal.type = 'human'
                     AND root_principal.status = 'active'
                     AND root_human.status = 'active'
                     AND root_human.disabled = 0
                     AND root_grant.revoked_at IS NULL
                     AND root_role.key = 'root'
                ) > 1
              )
            RETURNING id`
      : `UPDATE principals
              SET status = 'active', disabled_at = NULL, updated_at = ?
             WHERE id = ? AND type = 'human' AND status = 'disabled'
             RETURNING id`,
  ).bind(...(disabled ? [now, now, target.principal_id] : [now, target.principal_id]));

  const results = await environment.DB.batch([
    mutation,
    environment.DB.prepare(
      `UPDATE human_principals
          SET status = ?, disabled = ?, disabled_at = ?, updated_at = ?
          WHERE principal_id = ?
            AND EXISTS (
              SELECT 1 FROM principals
               WHERE id = ? AND status = ? AND updated_at = ?
            )`,
    ).bind(
      nextStatus,
      disabled ? 1 : 0,
      disabled ? now : null,
      now,
      target.principal_id,
      target.principal_id,
      nextStatus,
      now,
    ),
    ...(disabled
      ? [environment.DB.prepare("DELETE FROM session WHERE user_id = ?").bind(target.user_id)]
      : []),
    auditStatementWhen(
      environment.DB,
      `user:${disabled ? "disabled" : "enabled"}:${target.principal_id}:${now}`,
      `user.${disabled ? "disabled" : "enabled"}`,
      actor.principalId,
      target.principal_id,
      target.user_id,
      {},
      now,
      "SELECT 1 FROM principals WHERE id = ? AND status = ? AND updated_at = ?",
      [target.principal_id, nextStatus, now],
    ),
    outboxStatementWhen(
      environment.DB,
      `user:${disabled ? "disabled" : "enabled"}:outbox:${target.principal_id}:${now}`,
      `user.${disabled ? "disabled" : "enabled"}`,
      "principal",
      target.principal_id,
      { userId: target.user_id, status: nextStatus },
      now,
      "SELECT 1 FROM principals WHERE id = ? AND status = ? AND updated_at = ?",
      [target.principal_id, nextStatus, now],
    ),
  ]);

  if (!results[0]?.results.length) {
    const current = await resolveHumanPrincipal(environment.DB, identifier);
    if (current?.principal_status === nextStatus && current.human_status === nextStatus) {
      return {
        status: disabled ? ("disabled" as const) : ("active" as const),
        userId: current.user_id,
      };
    }
    throw new M1Error(409);
  }

  return { status: disabled ? ("disabled" as const) : ("active" as const), userId: target.user_id };
}

