index 00000000..80d66573
--- /dev/null
+++ b/src/server/m1/routes.ts
@@ -0,0 +1,183 @@
+import { Elysia } from "elysia";
+
+import {
+  type AuthEnvironment,
+  type AuthInstance,
+  isLocalEnvironment,
+  readDevelopmentEmailSink,
+} from "../auth";
+import { M1Error } from "./errors";
+import { M1Models } from "./models";
+import { requireRole } from "./authorization/service";
+import {
+  completeBootstrap,
+  completeSetup,
+  getBootstrapStatus,
+  reserveBootstrap,
+} from "./bootstrap/service";
+import {
+  claimInvitationWithAuth,
+  createInvitation,
+  getPublicInvitation,
+  revokeInvitation,
+} from "./invitations/service";
+import { setUserDisabled } from "./users/service";
+
+export function createM1Routes(environment: AuthEnvironment, auth: AuthInstance) {
+  return new Elysia({ name: "shui-m1-routes", normalize: false })
+    .model(M1Models)
+    .prefix("model", "M1.")
+    .error({ M1Error })
+    .onBeforeHandle(({ request, set }) => {
+      if (["POST", "PUT", "PATCH", "DELETE"].includes(request.method)) {
+        assertMutationOrigin(environment, request);
+      }
