-        )`,
-    ).bind(invitation.id, now),
-    auditStatementWhen(
-      environment.DB,
-      `invitation:revoked:${invitation.id}`,
-      "invitation.revoked",
-      actor.principalId,
-      null,
-      null,
-      { invitationId: invitation.id },
-      now,
-      "SELECT 1 FROM invitations WHERE id = ? AND status = 'revoked' AND revoked_at = ?",
-      [invitation.id, now],
-    ),
-    outboxStatementWhen(
-      environment.DB,
-      `invitation:revoked:outbox:${invitation.id}`,
-      "invitation.revoked",
-      "invitation",
-      invitation.id,
-      {},
-      now,
-      "SELECT 1 FROM invitations WHERE id = ? AND status = 'revoked' AND revoked_at = ?",
-      [invitation.id, now],
