        {error ? <FormError>{error}</FormError> : null}
        <Button
          aria-busy={isPending}
          className="w-full justify-center text-sm transition-none"
          disabled={isPending}
          type="submit"
          variant="primary"
        >
          {isPending ? "Creating account..." : "Accept invitation"}
        </Button>
      </form>
    </M1Layout>
  );
}

